mapper.select:
select * from( select batch_exe_id batchExeId, task_id taskId, busi_confirm_date busiConfirmDate, operator operator, file_type fileType, compres_file_id compresFileId, compres_file_name compresFileName, compres_file_path compresFilePath, file_count fileCount, record_count recordCount, deal_status dealStatus, deal_message dealMessage, consume_time consumeTime, start_time startTime, end_time endTime, gen_condition genCondition, create_user createUser, create_time createTime, update_user updateUser, update_time updateTime, create_dept createDept from CHB_SUBINFO_BATCH_LOG where 1=1
and REGEXP_SUBSTR(BUSI_CONFIRM_DATE, '[^ - ]+',1,3) >= #{busiConfirmDateStart,jdbcType=VARCHAR}
and REGEXP_SUBSTR(BUSI_CONFIRM_DATE, '[^ - ]+',1,1) <= #{busiConfirmDateEnd,jdbcType=VARCHAR}
and END_TIME >= STR_TO_DATE(#{queryDateStart,jdbcType=DATE},'%Y-%m-%d')
and START_TIME <= STR_TO_DATE(#{queryDateEnd,jdbcType=DATE},'%Y-%m-%d') + 1
and FILE_TYPE = #{fileType,jdbcType=VARCHAR}
and DEAL_STATUS = #{dealStatus,jdbcType=VARCHAR}
and OPERATOR = #{operator,jdbcType=VARCHAR}
) tmp

select
from CHB_SUBINFO_BATCH_LOG where 1=1
and DEAL_STATUS = #{dealStatus,jdbcType=VARCHAR}
